mapper.select:
SELECT 
        FROM local_client_public_capability_states WHERE status = 'UPDATE_AVAILABLE'
        ORDER BY updated_at, client_instance_id LIMIT #{limit}

mapper.update:
UPDATE local_client_instances SET public_capability_commit=#{activeCommit},
        public_capability_digest=#{activeDigest}, public_capability_status=#{status},
        public_capability_reported_at=#{reportedAt} WHERE client_instance_id=#{clientInstanceId}

mapper.select:
SELECT 
        FROM local_client_public_capability_attempts WHERE status IN ('PENDING','SENT','DOWNLOADING','APPLYING')
        ORDER BY created_at, command_id LIMIT #{limit}

mapper.update:
UPDATE local_client_public_capability_attempts
        SET connection_generation=#{targetGeneration}, updated_at=#{observedAt}
        WHERE command_id=#{commandId} AND connection_generation=#{expectedGeneration}
        AND status IN ('PENDING','SENT','DOWNLOADING')

UPDATE local_client_public_capability_attempts SET status=#{targetStatus},
        error_code=#{errorCode}, updated_at=#{observedAt}, completed_at=#{observedAt}NULL
        WHERE command_id=#{commandId} AND status=#{expectedStatus}
